PRAGMA foreign_keys=ON;
CREATE TABLE institutions(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,role TEXT NOT NULL CHECK(role IN ('student','teacher','partner')),name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,cpf TEXT UNIQUE,rg TEXT,address TEXT,institution_id TEXT REFERENCES institutions(id),course TEXT,department TEXT,balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE offers(id TEXT PRIMARY KEY,partner_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,photo TEXT NOT NULL,cost INTEGER NOT NULL CHECK(cost>0),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE coupons(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,student_id TEXT NOT NULL REFERENCES users(id),partner_id TEXT NOT NULL REFERENCES users(id),offer_id TEXT NOT NULL REFERENCES offers(id),title TEXT NOT NULL,cost INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','used')),request_key TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,used_at TEXT);
CREATE TABLE transactions(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('semester','recognition','redemption')),from_id TEXT REFERENCES users(id),to_id TEXT REFERENCES users(id),amount INTEGER NOT NULL CHECK(amount>0),reason TEXT NOT NULL,coupon_id TEXT UNIQUE REFERENCES coupons(id),semester TEXT,request_key TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(to_id,semester),CHECK((kind='semester' AND from_id IS NULL AND to_id IS NOT NULL AND semester IS NOT NULL) OR (kind='recognition' AND from_id IS NOT NULL AND to_id IS NOT NULL) OR (kind='redemption' AND from_id IS NOT NULL AND to_id IS NULL AND coupon_id IS NOT NULL)));
CREATE TABLE emails(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,transaction_id TEXT NOT NULL REFERENCES transactions(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','failed')),error TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_transactions_from ON transactions(from_id,created_at);
CREATE INDEX ix_transactions_to ON transactions(to_id,created_at);
CREATE INDEX ix_emails_user ON emails(user_id,created_at);
CREATE TRIGGER prevent_overdraft BEFORE INSERT ON transactions WHEN NEW.from_id IS NOT NULL AND (SELECT balance FROM users WHERE id=NEW.from_id)<NEW.amount BEGIN SELECT RAISE(ABORT,'Saldo insuficiente'); END;
CREATE TRIGGER apply_debit AFTER INSERT ON transactions WHEN NEW.from_id IS NOT NULL BEGIN UPDATE users SET balance=balance-NEW.amount WHERE id=NEW.from_id; END;
CREATE TRIGGER apply_credit AFTER INSERT ON transactions WHEN NEW.to_id IS NOT NULL BEGIN UPDATE users SET balance=balance+NEW.amount WHERE id=NEW.to_id; END;
